//! Scoped public ebook catalog. Guest chooses numeric IDs, never download URLs or paths.
use crate::Result;use serde_json::Value;
fn text(v:&Value,n:usize)->bool{v.as_str().is_some_and(|s|s.chars().count()<=n&&!s.chars().any(char::is_control))}
pub(crate) fn request(service:&str,a:&Value)->Result<()>{let o=a.as_object().ok_or("Use ebook arguments")?;match service{
 "ebooks.search"=>{if o.keys().any(|k|!["query","start"].contains(&k.as_str()))||a.get("query").is_some_and(|v|!text(v,100))||a.get("start").is_some_and(|v|v.as_u64().is_none_or(|n|!(1..=1_000_000).contains(&n))){return Err("Invalid ebook search".into())}},
 "ebooks.acquire"=>{if o.len()!=1||a["id"].as_u64().is_none_or(|n|!(1..=10_000_000).contains(&n)){return Err("Choose a Project Gutenberg book".into())}},_=>return Err("Unsupported ebook service".into())};Ok(())}
pub(crate) fn reply(service:&str,v:&Value)->Result<()>{if v.to_string().len()>65536{return Err("Ebook reply too large".into())}if service=="ebooks.search"{let rows=v["items"].as_array().filter(|r|r.len()<=25).ok_or("Invalid catalog page")?;for r in rows{if r["id"].as_u64().is_none_or(|n|!(1..=10_000_000).contains(&n))||!text(&r["title"],200)||!text(&r["author"],200){return Err("Invalid catalog book".into())}}if !v["next"].is_null()&&v["next"].as_u64().is_none_or(|n|!(1..=1_000_000).contains(&n)){return Err("Invalid catalog continuation".into())}}else if v["id"].as_str().is_none_or(|s|s.len()!=32||!s.bytes().all(|b|b.is_ascii_hexdigit()))||v["ready"]!=true{return Err("Ebook file was not committed".into())}Ok(())}
#[cfg(test)]mod tests{use super::*;use serde_json::json;#[test]fn ebook_requests_accept_only_bounded_catalog_ids(){request("ebooks.search",&json!({"query":"Carroll","start":26})).unwrap();request("ebooks.acquire",&json!({"id":11})).unwrap();for a in [json!({"id":11,"url":"https://evil.example/x"}),json!({"id":"../file"}),json!({"id":0})]{assert!(request("ebooks.acquire",&a).is_err())}assert!(request("ebooks.search",&json!({"query":"x".repeat(101)})).is_err())}#[test]fn ebook_replies_are_pages_not_unbounded_scrapes(){assert!(reply("ebooks.search",&json!({"items":vec![json!({"id":11,"title":"Book","author":"A"});26],"next":null})).is_err());reply("ebooks.search",&json!({"items":[{"id":11,"title":"Book","author":"A"}],"next":26})).unwrap();assert!(reply("ebooks.acquire",&json!({"id":"/tmp/file","ready":true})).is_err())}}
